'use strict';

// Prepare an uploaded Answer-me-with-html page for the public gallery.
// The file in pages/ is left as the author uploaded it; this runs at build
// time when copying into dist/.
//
// Removes:
// - the Reply / 回复 toolbar button (without it, the page script does not
//   inject panel comment boxes)
// - the Remark / 标注 toolbar button
// - the "Generated by Answer me with HTML" colophon above the title
//
// Leaves theme, mode, text size, and Copy source / 复制源稿 in place.

function isChromeButton(tag) {
  return /\bdata-am\s*=\s*(["'])(?:reply|remark)\1/i.test(tag)
    || /\bam-btn--(?:reply|remark)\b/i.test(tag);
}

function prepareAmPage(html) {
  let out = String(html);
  out = out.replace(/<button\b[^>]*>[\s\S]*?<\/button>/gi, (tag) => (
    isChromeButton(tag) ? '' : tag
  ));
  out = out.replace(
    /<p\b[^>]*\bclass\s*=\s*(["'])[^"']*\bam-colophon\b[^"']*\1[^>]*>[\s\S]*?<\/p>/gi,
    '',
  );
  return out;
}

module.exports = { prepareAmPage };
